:root {
  color: #172033;
  background: #eef2f7;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  --sev-p1: #c01e1e;
  --sev-p2: #d97706;
  --sev-p3: #2563eb;
  --sev-p4: #4b5563;
}

* { box-sizing: border-box; }

body { margin: 0; }
main {
  width: min(880px, calc(100% - 32px));
  margin: 24px auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
header, .filters, .summary, article, .detail-card, .timeline {
  background: white;
  border: 1px solid #d8e0ea;
  border-radius: 14px;
  padding: 16px;
}
.eyebrow { color: #3154a5; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; margin: 0; }
h1 { margin: 4px 0; font-size: 1.4rem; }
header p:last-child { margin: 0; color: #5b6577; }

.summary { display: flex; flex-wrap: wrap; gap: 12px; }
.summary .stat {
  flex: 1 1 110px;
  background: #f4f7fb;
  border-radius: 10px;
  padding: 10px 12px;
  border: 1px solid #e2e8f0;
}
.summary .stat .label { font-size: 0.72rem; text-transform: uppercase; color: #5b6577; letter-spacing: .06em; }
.summary .stat .value { font-size: 1.5rem; font-weight: 700; }

.filters { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; }
label { display: grid; gap: 4px; font-size: 0.8rem; color: #5b6577; }
input, select, button {
  box-sizing: border-box;
  min-height: 40px;
  padding: 8px 10px;
  font: inherit;
  border: 1px solid #c4cdda;
  border-radius: 8px;
  background: white;
  color: inherit;
}
button {
  border: 0;
  border-radius: 8px;
  color: white;
  background: #3154a5;
  font-weight: 700;
  cursor: pointer;
}
button:hover { background: #284280; }
button:disabled { background: #9aa4b8; cursor: default; }
button.secondary { background: #4b5563; }
button.danger { background: var(--sev-p1); }
button.success { background: #15803d; }

#feedback { min-height: 1.2em; margin: 0; font-weight: 600; }
#feedback.error { color: var(--sev-p1); }
#feedback.success { color: #15803d; }

#incident-list { display: grid; gap: 8px; }
.incident-row {
  display: grid;
  grid-template-columns: 8px 56px 1fr auto auto;
  gap: 10px;
  align-items: center;
  background: white;
  border: 1px solid #d8e0ea;
  border-radius: 12px;
  padding: 12px;
  cursor: pointer;
}
.incident-row.selected { border-color: #3154a5; box-shadow: 0 0 0 2px rgba(49, 84, 165, 0.2); }
.incident-row .sev-bar { width: 8px; height: 100%; min-height: 40px; border-radius: 4px; }
.sev-bar.P1 { background: var(--sev-p1); }
.sev-bar.P2 { background: var(--sev-p2); }
.sev-bar.P3 { background: var(--sev-p3); }
.sev-bar.P4 { background: var(--sev-p4); }
.incident-row .badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 6px;
  text-align: center;
}
.badge.P1 { background: #fde2e2; color: var(--sev-p1); }
.badge.P2 { background: #fef3c7; color: var(--sev-p2); }
.badge.P3 { background: #dbeafe; color: var(--sev-p3); }
.badge.P4 { background: #e5e7eb; color: var(--sev-p4); }
.incident-row .title { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.incident-row .meta { font-size: 0.78rem; color: #5b6577; }
.status-pill { font-size: 0.72rem; padding: 3px 8px; border-radius: 999px; font-weight: 600; }
.status-pill.open { background: #fef3c7; color: #92400e; }
.status-pill.acknowledged { background: #dbeafe; color: #1e40af; }
.status-pill.resolved { background: #d1fae5; color: #065f46; }
.alert-count { font-size: 0.78rem; color: #5b6577; }

#incident-detail .detail-card { display: grid; gap: 12px; }
.detail-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; flex-wrap: wrap; }
.detail-header h2 { margin: 0; font-size: 1.15rem; }
.detail-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 8px; }
.detail-grid .field .label { font-size: 0.7rem; text-transform: uppercase; color: #5b6577; }
.detail-grid .field .val { font-weight: 600; }

.controls { display: flex; gap: 8px; flex-wrap: wrap; align-items: end; }
.controls label { flex: 1 1 180px; }

.timeline { }
.timeline h3 { margin: 0 0 10px; font-size: 1rem; }
.timeline ol { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.timeline li {
  border-left: 3px solid #3154a5;
  padding: 6px 10px;
  background: #f4f7fb;
  border-radius: 0 8px 8px 0;
  font-size: 0.85rem;
}
.timeline li .ev-type { font-weight: 700; text-transform: capitalize; }
.timeline li .ev-time { color: #5b6577; font-size: 0.75rem; }
.timeline li .ev-details { color: #5b6577; font-size: 0.8rem; word-break: break-word; }

.empty { color: #5b6577; text-align: center; padding: 24px; }

@media (max-width: 560px) {
  main { width: calc(100% - 16px); margin: 12px auto; gap: 12px; }
  .filters { flex-direction: column; align-items: stretch; }
  .incident-row { grid-template-columns: 8px 48px 1fr; }
  .incident-row .alert-count, .incident-row .meta-extra { display: none; }
  .detail-grid { grid-template-columns: 1fr 1fr; }
  .controls { flex-direction: column; align-items: stretch; }
}

