(function () {
  "use strict";

  const state = {
    incidents: [],
    selectedId: null,
    selectedDetail: null,
    filters: { status: "", severity: "", owner: "" },
    feedback: "",
  };

  const el = {
    summary: document.getElementById("summary"),
    list: document.getElementById("incident-list"),
    detail: document.getElementById("incident-detail"),
    feedback: document.getElementById("feedback"),
    statusFilter: document.getElementById("status-filter"),
    severityFilter: document.getElementById("severity-filter"),
    escalateBtn: document.getElementById("escalate-btn"),
  };

  function setFeedback(message, kind) {
    state.feedback = message || "";
    el.feedback.textContent = message || "";
    el.feedback.className = kind || "";
  }

  function buildQuery() {
    const params = new URLSearchParams();
    if (state.filters.status) params.set("status", state.filters.status);
    if (state.filters.severity) params.set("severity", state.filters.severity);
    if (state.filters.owner) params.set("owner", state.filters.owner);
    const qs = params.toString();
    return qs ? "?" + qs : "";
  }

  async function fetchJSON(url, options) {
    const response = await fetch(url, options);
    let body = null;
    const text = await response.text();
    if (text) {
      try { body = JSON.parse(text); } catch (e) { body = { error: text }; }
    }
    return { ok: response.ok, status: response.status, body };
  }

  async function refresh() {
    try {
      const { ok, body } = await fetchJSON("/api/incidents" + buildQuery());
      if (!ok) { setFeedback("Failed to load incidents: " + (body && body.error), "error"); return; }
      state.incidents = body || [];
      renderSummary();
      renderList();
      if (state.selectedId) {
        await refreshDetail();
      }
    } catch (err) {
      setFeedback("Network error: " + err.message, "error");
    }
  }

  async function refreshSummary() {
    const { ok, body } = await fetchJSON("/api/summary");
    if (!ok) return;
    renderSummaryData(body);
  }

  function renderSummary() {
    refreshSummary();
  }

  function renderSummaryData(data) {
    const stats = [];
    stats.push(statCard("Total", data.total));
    const byStatus = data.by_status || {};
    for (const key of ["open", "acknowledged", "resolved"]) {
      stats.push(statCard(capitalize(key), byStatus[key] || 0));
    }
    const bySev = data.by_severity || {};
    for (const key of ["P1", "P2", "P3", "P4"]) {
      stats.push(statCard(key, bySev[key] || 0));
    }
    el.summary.replaceChildren(...stats);
  }

  function statCard(label, value) {
    const div = document.createElement("div");
    div.className = "stat";
    const lab = document.createElement("div");
    lab.className = "label";
    lab.textContent = label;
    const val = document.createElement("div");
    val.className = "value";
    val.textContent = String(value);
    div.appendChild(lab);
    div.appendChild(val);
    return div;
  }

  function renderList() {
    if (!state.incidents.length) {
      const p = document.createElement("p");
      p.className = "empty";
      p.textContent = "No incidents match the current filters.";
      el.list.replaceChildren(p);
      return;
    }
    el.list.replaceChildren(...state.incidents.map(renderRow));
  }

  function renderRow(incident) {
    const row = document.createElement("div");
    row.className = "incident-row";
    if (incident.id === state.selectedId) row.classList.add("selected");
    row.setAttribute("data-testid", "incident-row");
    row.dataset.id = incident.id;

    const bar = document.createElement("div");
    bar.className = "sev-bar " + incident.severity;

    const badge = document.createElement("div");
    badge.className = "badge " + incident.severity;
    badge.textContent = incident.severity;

    const main = document.createElement("div");
    const title = document.createElement("div");
    title.className = "title";
    title.textContent = incident.title;
    const meta = document.createElement("div");
    meta.className = "meta";
    meta.textContent = formatMeta(incident);
    main.appendChild(title);
    main.appendChild(meta);

    const pill = document.createElement("span");
    pill.className = "status-pill " + incident.status;
    pill.textContent = incident.status;

    const count = document.createElement("span");
    count.className = "alert-count meta-extra";
    count.textContent = incident.alert_count + " alert" + (incident.alert_count !== 1 ? "s" : "");

    row.appendChild(bar);
    row.appendChild(badge);
    row.appendChild(main);
    row.appendChild(pill);
    row.appendChild(count);

    row.addEventListener("click", () => selectIncident(incident.id));
    return row;
  }

  function formatMeta(incident) {
    const owner = incident.owner || "unassigned";
    const esc = incident.escalation_level > 0 ? " · esc " + incident.escalation_level : "";
    return owner + esc + " · v" + incident.version;
  }

  async function selectIncident(id) {
    state.selectedId = id;
    renderList();
    await refreshDetail();
  }

  async function refreshDetail() {
    if (!state.selectedId) { el.detail.hidden = true; return; }
    const { ok, body } = await fetchJSON("/api/incidents/" + encodeURIComponent(state.selectedId));
    if (!ok) {
      setFeedback("Failed to load incident: " + (body && body.error), "error");
      el.detail.hidden = true;
      return;
    }
    state.selectedDetail = body;
    renderDetail(body);
  }

  function renderDetail(incident) {
    el.detail.hidden = false;
    el.detail.replaceChildren();

    const card = document.createElement("div");
    card.className = "detail-card";

    const header = document.createElement("div");
    header.className = "detail-header";
    const h2 = document.createElement("h2");
    h2.textContent = incident.title;
    const badge = document.createElement("div");
    badge.className = "badge " + incident.severity;
    badge.textContent = incident.severity;
    header.appendChild(h2);
    header.appendChild(badge);
    card.appendChild(header);

    const grid = document.createElement("div");
    grid.className = "detail-grid";
    grid.appendChild(field("ID", incident.id));
    grid.appendChild(field("Status", incident.status));
    grid.appendChild(field("Severity", incident.severity));
    grid.appendChild(field("Owner", incident.owner || "—"));
    grid.appendChild(field("Alert count", incident.alert_count));
    grid.appendChild(field("Version", incident.version));
    grid.appendChild(field("Escalation", incident.escalation_level));
    grid.appendChild(field("Fingerprint", incident.fingerprint));
    grid.appendChild(field("Created", fmtTime(incident.created_at)));
    grid.appendChild(field("Updated", fmtTime(incident.updated_at)));
    grid.appendChild(field("SLA deadline", fmtTime(incident.sla_deadline)));
    card.appendChild(grid);

    const controls = document.createElement("div");
    controls.className = "controls";

    const ownerLabel = document.createElement("label");
    ownerLabel.textContent = "Owner";
    const ownerInput = document.createElement("input");
    ownerInput.setAttribute("data-testid", "owner-input");
    ownerInput.value = incident.owner || "";
    ownerInput.placeholder = "Assign owner";
    ownerLabel.appendChild(ownerInput);
    controls.appendChild(ownerLabel);

    const ackBtn = document.createElement("button");
    ackBtn.setAttribute("data-testid", "acknowledge-action");
    ackBtn.textContent = "Acknowledge";
    ackBtn.className = "secondary";
    ackBtn.disabled = incident.status !== "open";
    ackBtn.addEventListener("click", () => doUpdate(incident, { status: "acknowledged" }));

    const resolveBtn = document.createElement("button");
    resolveBtn.setAttribute("data-testid", "resolve-action");
    resolveBtn.textContent = "Resolve";
    resolveBtn.className = "success";
    resolveBtn.disabled = incident.status === "resolved";
    resolveBtn.addEventListener("click", () => doUpdate(incident, { status: "resolved" }));

    const assignBtn = document.createElement("button");
    assignBtn.textContent = "Set owner";
    assignBtn.addEventListener("click", () => doUpdate(incident, { owner: ownerInput.value }));

    controls.appendChild(ackBtn);
    controls.appendChild(resolveBtn);
    controls.appendChild(assignBtn);
    card.appendChild(controls);

    const timeline = document.createElement("div");
    timeline.setAttribute("data-testid", "timeline");
    timeline.className = "timeline";
    const h3 = document.createElement("h3");
    h3.textContent = "Audit timeline";
    const ol = document.createElement("ol");
    const events = incident.events || [];
    if (events.length === 0) {
      const li = document.createElement("li");
      li.textContent = "No events recorded.";
      ol.appendChild(li);
    } else {
      for (const ev of events) {
        const li = document.createElement("li");
        const typeSpan = document.createElement("span");
        typeSpan.className = "ev-type";
        typeSpan.textContent = ev.type.replace(/_/g, " ");
        const timeSpan = document.createElement("span");
        timeSpan.className = "ev-time";
        timeSpan.textContent = " · " + fmtTime(ev.timestamp);
        const detSpan = document.createElement("div");
        detSpan.className = "ev-details";
        detSpan.textContent = JSON.stringify(ev.details || {});
        li.appendChild(typeSpan);
        li.appendChild(timeSpan);
        li.appendChild(detSpan);
        ol.appendChild(li);
      }
    }
    timeline.appendChild(h3);
    timeline.appendChild(ol);
    card.appendChild(timeline);

    el.detail.appendChild(card);
  }

  function field(label, value) {
    const f = document.createElement("div");
    f.className = "field";
    const lab = document.createElement("div");
    lab.className = "label";
    lab.textContent = label;
    const val = document.createElement("div");
    val.className = "val";
    val.textContent = String(value);
    f.appendChild(lab);
    f.appendChild(val);
    return f;
  }

  async function doUpdate(incident, changes) {
    const payload = Object.assign({ expected_version: incident.version }, changes);
    const { ok, status, body } = await fetchJSON(
      "/api/incidents/" + encodeURIComponent(incident.id),
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      }
    );
    if (ok) {
      setFeedback("Updated " + incident.id, "success");
      await refresh();
    } else {
      const msg = (body && body.error) || ("HTTP " + status);
      setFeedback(msg, "error");
      await refresh();
    }
  }

  async function runEscalation() {
    const { ok, body } = await fetchJSON("/api/escalations/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "{}",
    });
    if (ok) {
      setFeedback("Escalated " + (body.count || 0) + " incident(s)", "success");
      await refresh();
    } else {
      setFeedback("Escalation failed: " + ((body && body.error) || "error"), "error");
    }
  }

  function capitalize(s) { return s.charAt(0).toUpperCase() + s.slice(1); }

  function fmtTime(ts) {
    if (!ts && ts !== 0) return "—";
    const d = new Date(ts * 1000);
    if (isNaN(d.getTime())) return String(ts);
    return d.toLocaleString();
  }

  el.statusFilter.addEventListener("change", () => {
    state.filters.status = el.statusFilter.value;
    refresh();
  });
  el.severityFilter.addEventListener("change", () => {
    state.filters.severity = el.severityFilter.value;
    refresh();
  });
  el.escalateBtn.addEventListener("click", runEscalation);

  window.incidentOps = {
    refresh: refresh,
    selectIncident: selectIncident,
    getState: function () {
      return {
        filters: Object.assign({}, state.filters),
        selectedIncidentId: state.selectedId,
        incidents: state.incidents.slice(),
        feedback: state.feedback,
      };
    },
  };

  refresh();
})();

