"""Tests for the HTTP API."""

from __future__ import annotations

import json
import threading
import time
import urllib.request

import pytest

from incident_ops.sqlite_store import SQLiteIncidentStore
from incident_ops.web import create_server


@pytest.fixture
def server(tmp_path):
    db = str(tmp_path / "http.db")
    store = SQLiteIncidentStore(db, clock=lambda: 100.0, dedupe_window=300, lease_seconds=30)
    srv = create_server(store, "127.0.0.1", 0)
    host, port = srv.server_address
    base = f"http://{host}:{port}"
    thread = threading.Thread(target=srv.serve_forever)
    thread.daemon = True
    thread.start()
    yield base, store
    srv.shutdown()
    srv.server_close()
    store.close()
    thread.join(timeout=5)


def request_json(base, method, path, body=None):
    url = base + path
    data = None
    headers = {}
    if body is not None:
        data = json.dumps(body).encode()
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=5) as resp:
            return resp.status, json.loads(resp.read().decode())
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode()
        try:
            return exc.code, json.loads(raw)
        except json.JSONDecodeError:
            return exc.code, raw


class TestAlerts:
    def test_post_alert_creates_incident_201(self, server):
        base, _ = server
        status, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "DB down", "severity": "P1",
        })
        assert status == 201
        assert body["fingerprint"] == "fp1"
        assert body["status"] == "open"
        assert body["severity"] == "P1"
        assert body["alert_count"] == 1

    def test_duplicate_alert_returns_200(self, server):
        base, _ = server
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "DB down", "severity": "P1",
            "now": 100.0,
        })
        status, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "DB down", "severity": "P1",
            "now": 110.0,
        })
        assert status == 200
        assert body["alert_count"] == 2

    def test_missing_fields_returns_400(self, server):
        base, _ = server
        status, body = request_json(base, "POST", "/api/alerts", {"title": "x"})
        assert status == 400
        assert "fingerprint" in body["error"]

    def test_invalid_severity_returns_400(self, server):
        base, _ = server
        status, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp", "title": "x", "severity": "P9",
        })
        assert status == 400
        assert "severity" in body["error"]

    def test_invalid_json_returns_400(self, server):
        base, _ = server
        url = base + "/api/alerts"
        req = urllib.request.Request(
            url, data=b"not json", method="POST",
            headers={"Content-Type": "application/json"},
        )
        try:
            urllib.request.urlopen(req, timeout=5)
        except urllib.error.HTTPError as exc:
            assert exc.code == 400
            body = json.loads(exc.read().decode())
            assert "error" in body


class TestIncidents:
    def test_list_returns_array(self, server):
        base, _ = server
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "A", "severity": "P1",
        })
        status, body = request_json(base, "GET", "/api/incidents")
        assert status == 200
        assert isinstance(body, list)
        assert len(body) == 1

    def test_list_with_filters(self, server):
        base, _ = server
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "a", "title": "A", "severity": "P1", "now": 100.0,
        })
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "b", "title": "B", "severity": "P2", "now": 101.0,
        })
        status, body = request_json(base, "GET", "/api/incidents?severity=P1")
        assert status == 200
        assert len(body) == 1
        assert body[0]["severity"] == "P1"

    def test_detail_includes_events(self, server):
        base, _ = server
        _, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "A", "severity": "P1", "now": 100.0,
        })
        inc_id = body["id"]
        status, detail = request_json(base, "GET", f"/api/incidents/{inc_id}")
        assert status == 200
        assert "events" in detail
        assert len(detail["events"]) == 1
        assert detail["events"][0]["type"] == "created"

    def test_detail_404(self, server):
        base, _ = server
        status, body = request_json(base, "GET", "/api/incidents/missing")
        assert status == 404


class TestPatch:
    def test_patch_update_owner_and_status(self, server):
        base, _ = server
        _, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "A", "severity": "P1", "now": 100.0,
        })
        inc_id = body["id"]
        status, updated = request_json(base, "PATCH", f"/api/incidents/{inc_id}", {
            "expected_version": 1, "owner": "raj", "status": "acknowledged",
        })
        assert status == 200
        assert updated["owner"] == "raj"
        assert updated["status"] == "acknowledged"
        assert updated["version"] == 2

    def test_patch_stale_version_returns_409(self, server):
        base, _ = server
        _, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "A", "severity": "P1", "now": 100.0,
        })
        inc_id = body["id"]
        request_json(base, "PATCH", f"/api/incidents/{inc_id}", {
            "expected_version": 1, "owner": "raj", "now": 110.0,
        })
        status, body = request_json(base, "PATCH", f"/api/incidents/{inc_id}", {
            "expected_version": 1, "owner": "other", "now": 120.0,
        })
        assert status == 409

    def test_patch_invalid_transition_returns_400(self, server):
        base, _ = server
        _, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "A", "severity": "P1", "now": 100.0,
        })
        inc_id = body["id"]
        request_json(base, "PATCH", f"/api/incidents/{inc_id}", {
            "expected_version": 1, "status": "acknowledged", "now": 110.0,
        })
        status, body = request_json(base, "PATCH", f"/api/incidents/{inc_id}", {
            "expected_version": 2, "status": "open", "now": 120.0,
        })
        assert status == 400

    def test_patch_missing_expected_version_400(self, server):
        base, _ = server
        _, body = request_json(base, "POST", "/api/alerts", {
            "fingerprint": "fp1", "title": "A", "severity": "P1", "now": 100.0,
        })
        status, body = request_json(base, "PATCH", f"/api/incidents/{body['id']}", {
            "owner": "raj",
        })
        assert status == 400


class TestSummary:
    def test_summary(self, server):
        base, _ = server
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "a", "title": "A", "severity": "P1", "now": 100.0,
        })
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "b", "title": "B", "severity": "P2", "now": 101.0,
        })
        status, body = request_json(base, "GET", "/api/summary")
        assert status == 200
        assert body["total"] == 2
        assert body["by_status"]["open"] == 2
        assert body["by_severity"]["P1"] == 1
        assert body["by_severity"]["P2"] == 1


class TestEscalationsRun:
    def test_escalations_run(self, server):
        base, _ = server
        request_json(base, "POST", "/api/alerts", {
            "fingerprint": "a", "title": "A", "severity": "P1", "now": 100.0,
        })
        status, body = request_json(base, "POST", "/api/escalations/run", {
            "worker_id": "api", "max_incidents": 5,
        })
        assert status == 200
        assert "escalated" in body
        assert body["count"] >= 0


class TestStaticFiles:
    def test_index_html(self, server):
        base, _ = server
        with urllib.request.urlopen(base + "/", timeout=5) as resp:
            assert resp.status == 200
            content = resp.read().decode()
            assert "incident-app" in content

