"""Tests for the HTTP API."""

from __future__ import annotations

import json
import threading
import time
import urllib.request

import pytest

from incident_ops.sqlite_store import SQLiteIncidentStore
from incident_ops.web import create_server


@pytest.fixture
def server(tmp_path):
    db = str(tmp_path / "http.db")
    store = SQLiteIncidentStore(db, clock=lambda: 100.0, dedupe_window=300, lease_seconds=30)
    srv = create_server(store, "127.0.0.1", 0)
    host, port = srv.server_address
    base = f"http://{host}:{port}"
    thread = threading.Thread(target=srv.serve_forever)
    thread.daemon = True
    thread.start()
    yield base, store
    srv.shutdown()
    srv.server_close()
    store.close()
    thread.join(timeout=5)


def request_json(base, method, path, body=None):
    url = base + path
    data = None
    headers = {}
    if body is not None:
        data = json.dumps(body).encode()
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=5) as resp:
            return resp.status, json.loads(resp.read().decode())
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode()
        try:
            return exc.code, json.loads(raw)
        except json.JSONDecodeError:
            return exc.code, raw


