"""Tests for the CLI across separate processes."""

from __future__ import annotations

import json
import os
import subprocess
import sys

import pytest

CLI = [sys.executable, "-m", "incident_ops.cli"]


def run_cli(db, *args, stdin=None, env=None):
    cmd = CLI + ["--db", db, *args]
    result = subprocess.run(
        cmd, input=stdin, capture_output=True, text=True, timeout=30, env=env,
    )
    return result


class TestIngest:
    def test_ingest_outputs_json(self, tmp_path):
        db = str(tmp_path / "cli.db")
        result = run_cli(db, "ingest", json.dumps({
            "fingerprint": "fp1", "title": "DB down", "severity": "P1",
        }))
        assert result.returncode == 0, result.stderr
        incident = json.loads(result.stdout)
        assert incident["fingerprint"] == "fp1"
        assert incident["status"] == "open"

    def test_ingest_missing_field_exits_nonzero(self, tmp_path):
        db = str(tmp_path / "cli.db")
        result = run_cli(db, "ingest", json.dumps({"title": "x"}))
        assert result.returncode != 0
        assert "fingerprint" in result.stderr

    def test_ingest_invalid_json_exits_nonzero(self, tmp_path):
        db = str(tmp_path / "cli.db")
        result = run_cli(db, "ingest", "not json")
        assert result.returncode != 0


class TestList:
    def test_list_outputs_array(self, tmp_path):
        db = str(tmp_path / "cli.db")
        run_cli(db, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        run_cli(db, "ingest", json.dumps({
            "fingerprint": "b", "title": "B", "severity": "P2",
        }))
        result = run_cli(db, "list")
        assert result.returncode == 0
        incidents = json.loads(result.stdout)
        assert len(incidents) == 2

    def test_list_with_severity_filter(self, tmp_path):
        db = str(tmp_path / "cli.db")
        run_cli(db, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        run_cli(db, "ingest", json.dumps({
            "fingerprint": "b", "title": "B", "severity": "P2",
        }))
        result = run_cli(db, "list", "--severity", "P1")
        assert result.returncode == 0
        incidents = json.loads(result.stdout)
        assert len(incidents) == 1
        assert incidents[0]["severity"] == "P1"


class TestUpdate:
    def test_update_owner(self, tmp_path):
        db = str(tmp_path / "cli.db")
        res = run_cli(db, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        inc_id = json.loads(res.stdout)["id"]
        result = run_cli(db, "update", inc_id, json.dumps({
            "expected_version": 1, "owner": "raj",
        }))
        assert result.returncode == 0, result.stderr
        updated = json.loads(result.stdout)
        assert updated["owner"] == "raj"
        assert updated["version"] == 2

    def test_update_version_conflict_nonzero(self, tmp_path):
        db = str(tmp_path / "cli.db")
        res = run_cli(db, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        inc_id = json.loads(res.stdout)["id"]
        run_cli(db, "update", inc_id, json.dumps({
            "expected_version": 1, "owner": "raj",
        }))
        result = run_cli(db, "update", inc_id, json.dumps({
            "expected_version": 1, "owner": "other",
        }))
        assert result.returncode != 0
        assert "conflict" in result.stderr.lower()


class TestEscalate:
    def test_escalate_outputs_array(self, tmp_path):
        db = str(tmp_path / "cli.db")
        run_cli(db, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1", "now": 100.0,
        }))
        result = run_cli(db, "escalate", "--worker-id", "w1", "--max-incidents", "5")
        assert result.returncode == 0
        incidents = json.loads(result.stdout)
        assert isinstance(incidents, list)


class TestExportImport:
    def test_export_then_import_preserves_data(self, tmp_path):
        db1 = str(tmp_path / "export.db")
        run_cli(db1, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        run_cli(db1, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        export_res = run_cli(db1, "export")
        assert export_res.returncode == 0
        lines = [l for l in export_res.stdout.strip().split("\n") if l]
        assert len(lines) >= 2  # incident + events

        db2 = str(tmp_path / "import.db")
        import_res = run_cli(db2, "import", stdin=export_res.stdout)
        assert import_res.returncode == 0
        list_res = run_cli(db2, "list")
        incidents = json.loads(list_res.stdout)
        assert len(incidents) == 1
        assert incidents[0]["alert_count"] == 2

    def test_repeated_import_no_duplicates(self, tmp_path):
        db1 = str(tmp_path / "export.db")
        run_cli(db1, "ingest", json.dumps({
            "fingerprint": "a", "title": "A", "severity": "P1",
        }))
        export_res = run_cli(db1, "export")

        db2 = str(tmp_path / "import.db")
        run_cli(db2, "import", stdin=export_res.stdout)
        run_cli(db2, "import", stdin=export_res.stdout)
        list_res = run_cli(db2, "list")
        incidents = json.loads(list_res.stdout)
        assert len(incidents) == 1


class TestServeAcrossRestart:
    def test_state_survives_restart(self, tmp_path):
        db = str(tmp_path / "restart.db")
        # Ingest directly to populate the DB.
        run_cli(db, "ingest", json.dumps({
            "fingerprint": "fp1", "title": "DB down", "severity": "P1",
        }))
        # A second CLI invocation should see the same incident.
        result = run_cli(db, "list")
        incidents = json.loads(result.stdout)
        assert len(incidents) == 1
        assert incidents[0]["fingerprint"] == "fp1"

